package ticketing

import (
	"crypto/ed25519"
	"encoding/base64"
	"encoding/hex"
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// docs/TICKET_FORMAT.md is what the mobile gate scanner is built from. Its layout table and
// its worked example are generated by the functions below from the same constants and the
// same code that sign real tickets, and TestTicketFormatDocMatchesCode fails when the file
// and the code disagree. To rewrite the generated parts after a deliberate change:
//
//	TICKET_FORMAT_UPDATE=1 go test ./internal/ticketing -run TestTicketFormatDocMatchesCode

func ticketFormatDocPath() string {
	_, file, _, _ := runtime.Caller(0)
	return filepath.Join(filepath.Dir(file), "..", "..", "..", "docs", "TICKET_FORMAT.md")
}

func docLayoutTable() string {
	var b strings.Builder
	b.WriteString("| Offset | Size | Field | Encoding |\n|---|---|---|---|\n")
	for _, f := range PayloadLayout {
		fmt.Fprintf(&b, "| %d | %d | %s | %s |\n", f.Offset, f.Size, f.Name, f.Encoding)
	}
	fmt.Fprintf(&b, "\nTotal: **%d bytes**, which is exactly %d base64url characters. The signature is %d bytes, %d characters. ",
		PayloadSize, base64.RawURLEncoding.EncodedLen(PayloadSize), SignatureSize, base64.RawURLEncoding.EncodedLen(SignatureSize))
	total := len(TokenPrefix) + 1 + base64.RawURLEncoding.EncodedLen(PayloadSize) + 1 + base64.RawURLEncoding.EncodedLen(SignatureSize)
	fmt.Fprintf(&b, "The whole QR text is always **%d characters**.\n", total)
	return b.String()
}

func docWorkedExample(t testing.TB) string {
	t.Helper()
	seed, err := hex.DecodeString(TestSeedHex)
	require.NoError(t, err)
	signer, err := NewSigner("k1", seed)
	require.NoError(t, err)
	// The constants are the pair of RFC 8032 §7.1, test 1; the code must agree.
	require.Equal(t, TestPublicKeyHex, hex.EncodeToString(signer.PublicKey()))

	claims := exampleClaims()
	claims.KeyID = "k1"
	payload, err := EncodePayload(claims)
	require.NoError(t, err)
	message := SigningMessage(payload)
	signature := ed25519.Sign(ed25519.NewKeyFromSeed(seed), message)
	token, err := signer.Sign(exampleClaims())
	require.NoError(t, err)
	require.Equal(t, EncodeToken(payload, signature), token)

	verifier, err := NewVerifier(PublicKey{KeyID: "k1", Key: signer.PublicKey()})
	require.NoError(t, err)
	got, err := verifier.Verify(token)
	require.NoError(t, err)
	require.NoError(t, got.CheckEvent(1))
	require.NoError(t, got.CheckGate("N-LOWER"))
	require.ErrorIs(t, got.CheckEvent(2), ErrWrongEvent)
	require.ErrorIs(t, got.CheckGate("S-LOWER"), ErrWrongGate)

	// Three texts that must be refused, for the scanner's own tests.
	forged := claims
	forged.EventID = 2
	forgedPayload, err := EncodePayload(forged)
	require.NoError(t, err)
	forgedToken := EncodeToken(forgedPayload, signature)
	_, err = verifier.Verify(forgedToken)
	require.ErrorIs(t, err, ErrBadSignature)

	last := token[len(token)-1]
	spare := "B"
	if last == 'B' {
		spare = "C"
	}
	nonCanonical := token[:len(token)-1] + spare
	_, err = verifier.Verify(nonCanonical)
	require.Error(t, err)
	nonCanonicalReason := "the last character has unused bits set: not canonical base64url"
	if err != ErrBadEncoding {
		nonCanonicalReason = "the signature does not match"
	}

	otherKey := claims
	otherKey.KeyID = "k2"
	otherPayload, err := EncodePayload(otherKey)
	require.NoError(t, err)
	otherToken := EncodeToken(otherPayload, ed25519.Sign(ed25519.NewKeyFromSeed(seed), SigningMessage(otherPayload)))
	_, err = verifier.Verify(otherToken)
	require.ErrorIs(t, err, ErrUnknownKey)

	field := func(i int) string {
		f := PayloadLayout[i]
		return hex.EncodeToString(payload[f.Offset : f.Offset+f.Size])
	}
	var b strings.Builder
	w := func(format string, args ...any) { fmt.Fprintf(&b, format, args...) }

	w("**Test key pair. TEST ONLY: this private key is public (it is test 1 of RFC 8032, section 7.1). The server refuses to start with it when `APP_ENV=production`. Never trust it on a real gate device.**\n\n")
	w("| | |\n|---|---|\n")
	w("| key ID | `k1` |\n")
	w("| private seed, 32 bytes, hex | `%s` |\n", TestSeedHex)
	w("| public key, 32 bytes, hex | `%s` |\n", TestPublicKeyHex)
	w("| public key, base64url (as `keys[].public_key` in the gate manifest) | `%s` |\n\n", base64.RawURLEncoding.EncodeToString(signer.PublicKey()))

	w("Payload fields:\n\n| Field | Value | Bytes (hex) |\n|---|---|---|\n")
	w("| version | 1 | `%s` |\n", field(0))
	w("| key number | 1 (key ID `k1`) | `%s` |\n", field(1))
	w("| ticket ID | `%s` | `%s` |\n", claims.TicketUUID(), field(2))
	w("| event ID | %d | `%s` |\n", claims.EventID, field(3))
	w("| gate group | `%s` (7 characters, then 9 zero bytes) | `%s` |\n", claims.GateGroup, field(4))
	w("| nonce | | `%s` |\n\n", field(5))

	w("Payload, %d bytes, hex:\n\n```\n%s\n```\n\n", len(payload), hex.EncodeToString(payload))
	w("Payload, base64url, %d characters:\n\n```\n%s\n```\n\n", len(tokenEncoding.EncodeToString(payload)), tokenEncoding.EncodeToString(payload))
	w("Context label, %d bytes, hex (the ASCII text `%s` and one zero byte):\n\n```\n%s\n```\n\n",
		len(SignatureContext), strings.TrimSuffix(SignatureContext, "\x00"), hex.EncodeToString([]byte(SignatureContext)))
	w("Signed message = context label then payload, %d bytes, hex:\n\n```\n%s\n```\n\n", len(message), hex.EncodeToString(message))
	w("Signature, %d bytes, hex:\n\n```\n%s\n```\n\n", len(signature), hex.EncodeToString(signature))
	w("Signature, base64url, %d characters:\n\n```\n%s\n```\n\n", len(tokenEncoding.EncodeToString(signature)), tokenEncoding.EncodeToString(signature))
	w("The QR text, %d characters:\n\n```\n%s\n```\n\n", len(token), token)

	w("What a scanner holding the test public key under `k1` must answer for it:\n\n")
	w("| Device is scanning | Result |\n|---|---|\n")
	w("| event 1, gate group `N-LOWER` | signature good, event good, gate good: admit (if the manifest says the ticket is `V`) |\n")
	w("| event 2, any gate group | `WRONG_EVENT` |\n")
	w("| event 1, gate group `S-LOWER` or `N-UPPER` | `WRONG_GATE` |\n\n")

	w("Three texts the same scanner must refuse as `INVALID`:\n\n")
	w("1. The payload says event 2, the signature is the one above (somebody edited the ticket). The signature does not match:\n\n```\n%s\n```\n\n", forgedToken)
	w("2. The QR text above with its last character changed from `%c` to `%s` (%s):\n\n```\n%s\n```\n\n", last, spare, nonCanonicalReason, nonCanonical)
	w("3. Key number 2 (`k2`), correctly signed with the test key, on a device that has only `k1`. The key ID is unknown:\n\n```\n%s\n```\n", otherToken)
	return b.String()
}

// replaceRegion swaps the text between <!-- name:begin --> and <!-- name:end --> lines.
func replaceRegion(t testing.TB, doc, name, body string) string {
	t.Helper()
	begin, end := "<!-- "+name+":begin -->\n", "<!-- "+name+":end -->"
	i := strings.Index(doc, begin)
	j := strings.Index(doc, end)
	require.True(t, i >= 0 && j > i, "docs/TICKET_FORMAT.md has no %q region", name)
	return doc[:i+len(begin)] + body + doc[j:]
}

func region(t testing.TB, doc, name string) string {
	t.Helper()
	begin, end := "<!-- "+name+":begin -->\n", "<!-- "+name+":end -->"
	i := strings.Index(doc, begin)
	j := strings.Index(doc, end)
	require.True(t, i >= 0 && j > i, "docs/TICKET_FORMAT.md has no %q region", name)
	return doc[i+len(begin) : j]
}

func TestTicketFormatDocMatchesCode(t *testing.T) {
	path := ticketFormatDocPath()
	raw, err := os.ReadFile(path)
	require.NoError(t, err)
	doc := string(raw)

	want := map[string]string{"layout": docLayoutTable(), "example": docWorkedExample(t)}
	if os.Getenv("TICKET_FORMAT_UPDATE") == "1" {
		for name, body := range want {
			doc = replaceRegion(t, doc, name, body)
		}
		require.NoError(t, os.WriteFile(path, []byte(doc), 0o644))
		t.Log("rewrote the generated parts of", path)
		return
	}
	for name, body := range want {
		assert.Equal(t, body, region(t, doc, name),
			"docs/TICKET_FORMAT.md (%s) no longer matches the code. If the code change is intended, run:\n  TICKET_FORMAT_UPDATE=1 go test ./internal/ticketing -run TestTicketFormatDocMatchesCode", name)
	}

	// The contract's example scan carries the same worked example, so the two documents
	// the mobile engineer reads show one token.
	spec, err := os.ReadFile(filepath.Join(filepath.Dir(path), "..", "backend", "docs", "openapi.yaml"))
	require.NoError(t, err)
	exampleToken, err := testSigner(t).Sign(exampleClaims())
	require.NoError(t, err)
	assert.Contains(t, string(spec), "token: "+exampleToken, "the uploadScans example in openapi.yaml should carry the worked example's token")
	assert.Contains(t, doc, exampleToken)

	// The prose outside the generated parts names these values; keep them honest too.
	for _, must := range []string{
		"`" + TokenPrefix + ".<payload>.<signature>`",
		"`" + strings.TrimSuffix(SignatureContext, "\x00") + "`",
		fmt.Sprintf("%d bytes", PayloadSize),
		"version 9",
		"53 x 53",
	} {
		assert.Contains(t, doc, must, "docs/TICKET_FORMAT.md should mention %s", must)
	}
}
